interface Service { suspend fun call(request: Request): Response }

class Gate(private val next: Service, private val rule: Rule) : Service by next {
    override suspend fun call(request: Request): Response {
        val id = verify(request)                     // this gate's own evidence
        if (!rule.allows(id, request)) throw Forbidden()   // fail closed
        return next.call(request)                    // delegate inward
    }
}
val service: Service = Gate(Gate(resource, tenantRule), edgeRule)   // gates nest
